def caesar_encrypt(text, shift):
    result = ""
    for char in text:
        if char.isalpha():
            base = ord('A') if char.isupper() else ord('a')
            shifted = (ord(char) - base + shift) % 26
            result += chr(shifted + base)
        else:
            result += char
    return result

encrypted = caesar_encrypt("HELLO", 3)  # KHOOR
decrypted = caesar_encrypt("KHOOR", -3) # HELLO
